SELECT m.*,COALESCE(NULLIF(u.nickname,''),u.username,'已注销用户') AS uploader_name
FROM material m LEFT JOIN user u ON m.uploader_id=u.user_id AND u.is_deleted=0

    m.is_deleted = 0
    AND m.status = #{status}

ORDER BY m.create_time DESC,m.material_id DESC

    LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM material m

    m.is_deleted = 0
    AND m.status = #{status}
